package io.scenariomesh.core;import io.scenariomesh.core.Domain.WorkerStatus;import java.util.*;public final class WorkerStateMachine{private WorkerStatus state=WorkerStatus.STARTING;private static final Map<WorkerStatus,Set<WorkerStatus>> ALLOWED=Map.of(WorkerStatus.STARTING,Set.of(WorkerStatus.READY,WorkerStatus.UNHEALTHY,WorkerStatus.DEAD),WorkerStatus.READY,Set.of(WorkerStatus.BUSY,WorkerStatus.IDLE,WorkerStatus.DRAINING,WorkerStatus.STOPPING,WorkerStatus.UNHEALTHY),WorkerStatus.IDLE,Set.of(WorkerStatus.BUSY,WorkerStatus.DRAINING,WorkerStatus.STOPPING,WorkerStatus.UNHEALTHY),WorkerStatus.BUSY,Set.of(WorkerStatus.READY,WorkerStatus.DRAINING,WorkerStatus.UNHEALTHY,WorkerStatus.DEAD),WorkerStatus.DRAINING,Set.of(WorkerStatus.STOPPING,WorkerStatus.DEAD),WorkerStatus.STOPPING,Set.of(WorkerStatus.STOPPED,WorkerStatus.DEAD),WorkerStatus.UNHEALTHY,Set.of(WorkerStatus.DRAINING,WorkerStatus.DEAD),WorkerStatus.STOPPED,Set.of(),WorkerStatus.DEAD,Set.of());public synchronized WorkerStatus state(){return state;}public synchronized void transition(WorkerStatus next){if(!ALLOWED.get(state).contains(next))throw new IllegalStateException("Invalid worker transition "+state+" -> "+next);state=next;}}
